function handler(event) {
  var request = event.request;
  var uri = request.uri;

  // ディレクトリパスの場合（末尾が / でない、かつ拡張子がない）
  if (!uri.includes('.') && !uri.endsWith('/')) {
    // /events -> /events/index.html
    request.uri = uri + '/index.html';
  } else if (uri.endsWith('/')) {
    // /events/ -> /events/index.html
    request.uri = uri + 'index.html';
  }

  return request;
}
